// Render only the native card components generated by our server. Business
// fields stay plain text; this is a preview, never a general Markdown renderer.
export function renderReminderCard(card, fallback = '') {
  const element = (tag, className, content) => {
    const node = document.createElement(tag); node.className = className;
    if (content !== undefined) node.textContent = content;
    return node;
  };
  if (card?.schema !== '2.0' || !Array.isArray(card.body?.elements)) return element('pre', '', fallback);
  const root = element('section', 'reminder-card');
  const tone = ['blue', 'orange', 'red'].includes(card.header?.template) ? card.header.template : 'blue';
  const header = element('header', 'reminder-card-header ' + tone);
  header.append(element('h3', '', card.header?.title?.content || ''), element('p', '', card.header?.subtitle?.content || ''));
  const body = element('div', 'reminder-card-body');
  for (const component of card.body.elements) {
    if (component.tag === 'div' && component.text?.tag === 'plain_text') body.append(element('p', 'reminder-card-text', component.text.content));
    else if (component.tag === 'hr') body.append(element('hr', ''));
    else if (component.tag === 'column_set') {
      const metrics = element('div', 'reminder-card-metrics');
      for (const column of (component.columns || []).slice(0, 3)) {
        const content = column.elements?.[0]?.content || '', match = /^### (\d+)\n([^\n]+)\n([^\n]+)$/.exec(content);
        if (!match) continue;
        const metric = element('div', 'reminder-card-metric');
        metric.append(element('strong', '', match[1]), element('span', '', match[2]), element('span', '', match[3])); metrics.append(metric);
      }
      body.append(metrics);
    } else if (component.tag === 'button') {
      const action = component.behaviors?.find(value => value.type === 'open_url');
      if (action?.default_url !== 'https://iqc.namecheap.xin/') continue;
      const link = element('a', 'reminder-card-action', component.text?.content || 'IQC');
      link.href = action.default_url; link.target = '_blank'; link.rel = 'noopener noreferrer'; body.append(link);
    }
  }
  root.append(header, body); return root;
}
